// Des: Tests for M13: owner sessions, profile reuse, caps, login wall
// Flo: mock cookie site > account fetches through a persistent profile > assert reuse, stop on wall, day cap, no vendor, no path in logs
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const acct = @import("ru-acct-guar.zig"); const rend = @import("nt-brow-rend.zig"); const cfgz = @import("cf-conf-load.zig"); const sqli = @import("st-stor-sqli.zig");
const allo = std.testing.allocator;
fn logi() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.logi_mode_enab = true; conf.rate_host_seco = 0; return conf; }
fn hasz(rig3: *rigz.Rigg, path: []const u8, nee2: []const u8) !bool { const recz = (try rig3.reco(path)) orelse return false; return std.mem.indexOf(u8, recz.body, nee2) != null; }
test "saved profile is reused: login once, later run (browser restarted) reads the gated page" { var rig3: rigz.Rigg = undefined; try rig3.upzz(logi()); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acct = "owner"; _ = try rig3.gozz("/login"); rig3.rndz.reset(); const out2 = try rig3.gozz("/acct"); try std.testing.expectEqualStrings("brow", out2.vend); try std.testing.expect(try hasz(&rig3, "/acct", "Account dashboard for owner")); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.cal3.items.len); }
test "no session: login wall stops the run, never retried, no vendor call" { var rig3: rigz.Rigg = undefined; try rig3.upzz(logi()); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acct = "owner"; try std.testing.expectError(error.LoginWall, rig3.gozz("/acct")); const rnzz = rig3.rndz.rnds; try std.testing.expectError(error.LoginWall, rig3.gozz("/acct")); try std.testing.expectEqual(rnzz, rig3.rndz.rnds); try std.testing.expectEqual(@as(usize, 0), rig3.vmkz.cal3.items.len); try acct.acctClea(&rig3.dbzz, "owner"); _ = try rig3.gozz("/login"); const out2 = try rig3.gozz("/acct"); try std.testing.expectEqualStrings("new", out2.stat); }
test "expired session mid-run stops and alerts through the wall flag" { var rig3: rigz.Rigg = undefined; try rig3.upzz(logi()); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acct = "owner"; _ = try rig3.gozz("/login"); _ = try rig3.gozz("/acct"); try acct.acctWall(&rig3.dbzz, "owner", 1); try std.testing.expectError(error.LoginWall, rig3.gozz("/acct?n=2")); }
test "daily page cap halts the account" { var conf = logi(); conf.acct_page_maxz = 2; var rig3: rigz.Rigg = undefined; try rig3.upzz(conf); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acct = "owner"; _ = try rig3.gozz("/login"); _ = try rig3.gozz("/acct"); const rnzz = rig3.rndz.rnds; try std.testing.expectError(error.DayCap, rig3.gozz("/acct?n=3")); try std.testing.expectEqual(rnzz, rig3.rndz.rnds); }
test "off unless logi_mode_enab and brow_enab" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); rig3.ladz.acct = "owner"; try std.testing.expectError(error.NotConfigured, rig3.gozz("/acct")); var rig2: rigz.Rigg = undefined; try rig2.upzz(logi()); defer rig2.down(); rig2.ladz.acct = "owner"; rig2.ladz.sess = null; try std.testing.expectError(error.NoBrowser, rig2.gozz("/acct")); }
test "one account = one profile: another account does not see the session" { var rig3: rigz.Rigg = undefined; try rig3.upzz(logi()); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acct = "owner"; _ = try rig3.gozz("/login"); const othe = try std.fs.path.join(allo, &.{ rig3.pro2, "other" }); defer allo.free(othe); var rnd2 = try rend.rndrInit(allo, std.testing.io, logi(), othe); defer rnd2.deinit(); rnd2.conf.brow_enab = true; rig3.ladz.sess = &rnd2; rig3.ladz.acct = "other"; try std.testing.expectError(error.LoginWall, rig3.gozz("/acct")); rig3.ladz.sess = &rig3.rndz; }
test "profile path never reaches the logs" { var rig3: rigz.Rigg = undefined; try rig3.upzz(logi()); defer rig3.down(); try rig3.skipNozz(); rig3.ladz.acct = "owner"; _ = rig3.gozz("/acct") catch {}; var stmt = try rig3.dbzz.prep("SELECT group_concat(note || ' ' || urlz || ' ' || vend, ' ') FROM logz;"); defer stmt.fini(); _ = try stmt.step(); const allz = stmt.colzText(0); try std.testing.expect(std.mem.indexOf(u8, allz, "prof") == null); try std.testing.expect(std.mem.indexOf(u8, allz, ".zig-cache") == null); }
test "spacing: accounts wait last + 3x rate_host_seco" { var rig3: rigz.Rigg = undefined; try rig3.upzz(.{}); defer rig3.down(); const t1zz = try acct.acctTake(&rig3.dbzz, "a", 1_000_000_000, 10, 3000); try std.testing.expectEqual(@as(u64, 0), t1zz.wait); const t2zz = try acct.acctTake(&rig3.dbzz, "a", 1_000_000_500, 10, 3000); try std.testing.expectEqual(@as(u64, 2500), t2zz.wait); const t3zz = try acct.acctTake(&rig3.dbzz, "a", 1_000_000_000 + 86_400_000, 10, 3000); try std.testing.expectEqual(@as(u64, 0), t3zz.wait); try std.testing.expectEqual(@as(i64, 1), try acct.acctUsed(&rig3.dbzz, "a", 1_000_000_000 + 86_400_000)); }
